def copy(src,relative,role):
    src=Path(src);dst=DEST/relative
    assert dst.resolve().is_relative_to(DEST.resolve()) and not dst.exists()
    assert src.is_file(),str(src)
    assert src.stat().st_size<50_000_000,f'Explicit50MB per-file review cap: {src}'
    dst.parent.mkdir(parents=True,exist_ok=True);before=sha(src);shutil.copy2(src,dst)
    assert sha(dst)==before
    assets.append({'path':dst.relative_to(DEST).as_posix(),'source':str(src),'bytes':dst.stat().st_size,'sha256':before,'role':role})
